from .collector import (
    LocalCaptureStrategy,
    RemoteCaptureStrategy,
    TcpdumpCollector,
    PdumpMirrorCollector)
from taf.internal.core import NamedComponentFactory
from taf.internal.execution.base import CreatingExecutor
from taf.internal.execution.base.executor_config import migrate_configuration
from taf.internal.file.transfer.base import CreatingFileGetter
import logging
import re

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class BaseTcpDumpCollectorFactory(
        CreatingExecutor('tool_executor'),
        NamedComponentFactory):
    _optional_parameters = {"options", "tcpdump_path", "target_file_name", "start_timeout", "stop_timeout"}
    _product_class = TcpdumpCollector


class RemoteCapturingTcpDumpCollectorFactory(
        CreatingFileGetter('file_getter'),
        BaseTcpDumpCollectorFactory):
    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        configuration['file_transfer'] = {
            'type': 'cat',
            'executor': configuration['executor']}
        super(RemoteCapturingTcpDumpCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments['capturing_strategy'] = RemoteCaptureStrategy(
            tool_executor=resulting_arguments["tool_executor"])


class LocalCapturingTcpDumpCollectorFactory(
        CreatingExecutor('local_executor', None),
        CreatingFileGetter('file_getter', None),
        BaseTcpDumpCollectorFactory):
    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(LocalCapturingTcpDumpCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments['capturing_strategy'] = LocalCaptureStrategy(
            local_executor=resulting_arguments.pop("local_executor"))


class TcpdumpCollectorFactorySelector(object):

    @staticmethod
    def _get_factory_class(factory_class):
        return factory_class

    @staticmethod
    def _create_factory(factory_class):
        return factory_class()

    def create(self, configuration, existing_arguments):
        factory_class = LocalCapturingTcpDumpCollectorFactory if configuration.get("capture_locally") else RemoteCapturingTcpDumpCollectorFactory
        factory = self._create_factory(self._get_factory_class(factory_class))
        if 'kubectl_exec_options' in configuration:
            namespace, pod, container = self._extract_namespace_pod_container_from_string(
                configuration.pop('kubectl_exec_options'))
            configuration['namespace'] = namespace
            configuration['pod'] = pod
            configuration['container'] = container
        configuration = migrate_configuration(configuration)
        return factory.create(
            configuration=configuration,
            existing_arguments=existing_arguments)

    @staticmethod
    def _extract_namespace_pod_container_from_string(kubectl_exec_options):
        match = re.findall(r"-n\s+(\S+)\s+(\S+)\s+-c\s+(\S+)", kubectl_exec_options)
        if match:
            return match[0]
        else:
            raise ValueError(
                "\"{kubectl_exec_options}\" is not in "
                "\"-n {{namespace}} {{pod}} -c {{container}}\" format".format(
                    kubectl_exec_options=kubectl_exec_options))


class PdumpMirrorCollectorFactory(
        CreatingExecutor('tool_executor'),
        NamedComponentFactory):
    _mandatory_parameters = {"port"}
    _product_class = PdumpMirrorCollector

    def create(self, configuration, existing_arguments):
        configuration = migrate_configuration(configuration)
        return super(PdumpMirrorCollectorFactory, self).create(configuration, existing_arguments)
